vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_manyfish sampler_noise_lq
sampler sampler_manyfish;
shader_body
{
vec2 d = (vec2(1.0)/uTexSize) * 8.0;
vec3 dx = ( GetBlur1(uv+vec2( 1.0 , 0.0 )*d)-GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
vec2 uv_y = uv-vec2(dx.y,dy.y)*0.4;
vec2 uv_dx = uv - vec2(dx.x,dy.x) * 1.0;
vec2 uv_dz = uv + vec2(dx.z,dy.z)*(vec2(1.0)/uTexSize) * 256.0;
vec2 uv_dy = uv - vec2(dx.y,dy.y)*(vec2(1.0)/uTexSize) * 80.0;
ret = GetPixel(uv).y*0.2;
vec4 noise9 = tex3D(sampler_noisevol_hq,
((uv_dz.xyy*q28
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3( 1.0 , 1.0 , 0.0 )*0.05 +
uTime*vec3( 0.0 , 0.0 , 1.0 )*q31
);
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5;
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5;
ret = mix(vec3(0.2, 0.0 ,0.1),vec3(0.8,0.6, 0.0),GetPixel(uv_dz).y);
ret = mix(ret, 1.0 ,GetPixel(uv).z * 1.0);
ret = mix(ret, vec3(0.8, 0.0 ,1.5), length(vec2(dx.x,dy.x)));
ret = mix(clamp01(ret), 0.0 ,clamp01(GetPixel(uv_dz).x-GetBlur1(uv).z*1.5));
//ret = GetPixel(uv).y;
}

