sampler sampler_manyfish;
shader_body
{
float2 d = texsize.zw*8;
float3 dx = ( GetBlur1(uv+float2(1,0)*d)-GetBlur1(uv-float2(1,0)*d) );
float3 dy = ( GetBlur1(uv+float2(0,1)*d)-GetBlur1(uv-float2(0,1)*d) );
float2 uv_y = uv-float2(dx.y,dy.y)*0.4;
float2 uv_dx = uv - float2(dx.x,dy.x)*1;
float2 uv_dz = uv + float2(dx.z,dy.z)*texsize.zw*256;
float2 uv_dy = uv - float2(dx.y,dy.y)*texsize.zw*80;
ret = GetPixel(uv).y*0.2;
float4 noise9 = tex3D(sampler_noisevol_hq,
((uv_dz.xyy*q28
)*texsize.xyy*texsize_noisevol_hq.zww
).xyz*
float3(1,1,0)*0.05 +
time*float3(0,0,1)*q31
);
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5;
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5;
ret = lerp(float3(0.2,0,0.1),float3(0.8,0.6,0),GetPixel(uv_dz).y);
ret = lerp(ret,1,GetPixel(uv).z*1);
ret = lerp(ret, float3(0.8,0,1.5), length(float2(dx.x,dy.x)));
ret = lerp(saturate(ret),0,saturate(GetPixel(uv_dz).x-GetBlur1(uv).z*1.5));
